mkitem!{mkstruct!{# [doc = " A pointer which pins its pointee in place."] # [doc = ""] # [doc = " [`Pin`] is a wrapper around some kind of pointer `Ptr` which makes that pointer \"pin\" its"] # [doc = " pointee value in place, thus preventing the value referenced by that pointer from being moved"] # [doc = " or otherwise invalidated at that place in memory unless it implements [`Unpin`]."] # [doc = ""] # [doc = " *See the [`pin` module] documentation for a more thorough exploration of pinning.*"] # [doc = ""] # [doc = " ## Pinning values with [`Pin<Ptr>`]"] # [doc = ""] # [doc = " In order to pin a value, we wrap a *pointer to that value* (of some type `Ptr`) in a"] # [doc = " [`Pin<Ptr>`]. [`Pin<Ptr>`] can wrap any pointer type, forming a promise that the **pointee**"] # [doc = " will not be *moved* or [otherwise invalidated][subtle-details]. If the pointee value's type"] # [doc = " implements [`Unpin`], we are free to disregard these requirements entirely and can wrap any"] # [doc = " pointer to that value in [`Pin`] directly via [`Pin::new`]. If the pointee value's type does"] # [doc = " not implement [`Unpin`], then Rust will not let us use the [`Pin::new`] function directly and"] # [doc = " we'll need to construct a [`Pin`]-wrapped pointer in one of the more specialized manners"] # [doc = " discussed below."] # [doc = ""] # [doc = " We call such a [`Pin`]-wrapped pointer a **pinning pointer** (or pinning ref, or pinning"] # [doc = " [`Box`], etc.) because its existence is the thing that is pinning the underlying pointee in"] # [doc = " place: it is the metaphorical \"pin\" securing the data in place on the pinboard (in memory)."] # [doc = ""] # [doc = " It is important to stress that the thing in the [`Pin`] is not the value which we want to pin"] # [doc = " itself, but rather a pointer to that value! A [`Pin<Ptr>`] does not pin the `Ptr` but rather"] # [doc = " the pointer's ***pointee** value*."] # [doc = ""] # [doc = " The most common set of types which require pinning related guarantees for soundness are the"] # [doc = " compiler-generated state machines that implement [`Future`] for the return value of"] # [doc = " `async fn`s. These compiler-generated [`Future`]s may contain self-referential pointers, one"] # [doc = " of the most common use cases for [`Pin`]. More details on this point are provided in the"] # [doc = " [`pin` module] docs, but suffice it to say they require the guarantees provided by pinning to"] # [doc = " be implemented soundly."] # [doc = ""] # [doc = " This requirement for the implementation of `async fn`s means that the [`Future`] trait"] # [doc = " requires all calls to [`poll`] to use a <code>self: [Pin]\\<&mut Self></code> parameter instead"] # [doc = " of the usual `&mut self`. Therefore, when manually polling a future, you will need to pin it"] # [doc = " first."] # [doc = ""] # [doc = " You may notice that `async fn`-sourced [`Future`]s are only a small percentage of all"] # [doc = " [`Future`]s that exist, yet we had to modify the signature of [`poll`] for all [`Future`]s"] # [doc = " to accommodate them. This is unfortunate, but there is a way that the language attempts to"] # [doc = " alleviate the extra friction that this API choice incurs: the [`Unpin`] trait."] # [doc = ""] # [doc = " The vast majority of Rust types have no reason to ever care about being pinned. These"] # [doc = " types implement the [`Unpin`] trait, which entirely opts all values of that type out of"] # [doc = " pinning-related guarantees. For values of these types, pinning a value by pointing to it with a"] # [doc = " [`Pin<Ptr>`] will have no actual effect."] # [doc = ""] # [doc = " The reason this distinction exists is exactly to allow APIs like [`Future::poll`] to take a"] # [doc = " [`Pin<Ptr>`] as an argument for all types while only forcing [`Future`] types that actually"] # [doc = " care about pinning guarantees pay the ergonomics cost. For the majority of [`Future`] types"] # [doc = " that don't have a reason to care about being pinned and therefore implement [`Unpin`], the"] # [doc = " <code>[Pin]\\<&mut Self></code> will act exactly like a regular `&mut Self`, allowing direct"] # [doc = " access to the underlying value. Only types that *don't* implement [`Unpin`] will be restricted."] # [doc = ""] # [doc = " ### Pinning a value of a type that implements [`Unpin`]"] # [doc = ""] # [doc = " If the type of the value you need to \"pin\" implements [`Unpin`], you can trivially wrap any"] # [doc = " pointer to that value in a [`Pin`] by calling [`Pin::new`]."] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " // Create a value of a type that implements `Unpin`"] # [doc = " let mut unpin_future = std::future::ready(5);"] # [doc = ""] # [doc = " // Pin it by creating a pinning mutable reference to it (ready to be `poll`ed!)"] # [doc = " let my_pinned_unpin_future: Pin<&mut _> = Pin::new(&mut unpin_future);"] # [doc = " ```"] # [doc = ""] # [doc = " ### Pinning a value inside a [`Box`]"] # [doc = ""] # [doc = " The simplest and most flexible way to pin a value that does not implement [`Unpin`] is to put"] # [doc = " that value inside a [`Box`] and then turn that [`Box`] into a \"pinning [`Box`]\" by wrapping it"] # [doc = " in a [`Pin`]. You can do both of these in a single step using [`Box::pin`]. Let's see an"] # [doc = " example of using this flow to pin a [`Future`] returned from calling an `async fn`, a common"] # [doc = " use case as described above."] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " async fn add_one(x: u32) -> u32 {"] # [doc = "     x + 1"] # [doc = " }"] # [doc = ""] # [doc = " // Call the async function to get a future back"] # [doc = " let fut = add_one(42);"] # [doc = ""] # [doc = " // Pin the future inside a pinning box"] # [doc = " let pinned_fut: Pin<Box<_>> = Box::pin(fut);"] # [doc = " ```"] # [doc = ""] # [doc = " If you have a value which is already boxed, for example a [`Box<dyn Future>`][Box], you can pin"] # [doc = " that value in-place at its current memory address using [`Box::into_pin`]."] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = " use std::future::Future;"] # [doc = ""] # [doc = " async fn add_one(x: u32) -> u32 {"] # [doc = "     x + 1"] # [doc = " }"] # [doc = ""] # [doc = " fn boxed_add_one(x: u32) -> Box<dyn Future<Output = u32>> {"] # [doc = "     Box::new(add_one(x))"] # [doc = " }"] # [doc = ""] # [doc = " let boxed_fut = boxed_add_one(42);"] # [doc = ""] # [doc = " // Pin the future inside the existing box"] # [doc = " let pinned_fut: Pin<Box<_>> = Box::into_pin(boxed_fut);"] # [doc = " ```"] # [doc = ""] # [doc = " There are similar pinning methods offered on the other standard library smart pointer types"] # [doc = " as well, like [`Rc`] and [`Arc`]."] # [doc = ""] # [doc = " ### Pinning a value on the stack using [`pin!`]"] # [doc = ""] # [doc = " There are some situations where it is desirable or even required (for example, in a `#[no_std]`"] # [doc = " context where you don't have access to the standard library or allocation in general) to"] # [doc = " pin a value which does not implement [`Unpin`] to its location on the stack. Doing so is"] # [doc = " possible using the [`pin!`] macro. See its documentation for more."] # [doc = ""] # [doc = " ## Layout and ABI"] # [doc = ""] # [doc = " [`Pin<Ptr>`] is guaranteed to have the same memory layout and ABI[^noalias] as `Ptr`."] # [doc = ""] # [doc = " [^noalias]: There is a bit of nuance here that is still being decided about whether the"] # [doc = " aliasing semantics of `Pin<&mut T>` should be different than `&mut T`, but this is true as of"] # [doc = " today."] # [doc = ""] # [doc = " [`pin!`]: crate::pin::pin \"pin!\""] # [doc = " [`Future`]: crate::future::Future \"Future\""] # [doc = " [`poll`]: crate::future::Future::poll \"Future::poll\""] # [doc = " [`Future::poll`]: crate::future::Future::poll \"Future::poll\""] # [doc = " [`pin` module]: self \"pin module\""] # [doc = " [`Rc`]: ../../std/rc/struct.Rc.html \"Rc\""] # [doc = " [`Arc`]: ../../std/sync/struct.Arc.html \"Arc\""] # [doc = " [Box]: ../../std/boxed/struct.Box.html \"Box\""] # [doc = " [`Box`]: ../../std/boxed/struct.Box.html \"Box\""] # [doc = " [`Box::pin`]: ../../std/boxed/struct.Box.html#method.pin \"Box::pin\""] # [doc = " [`Box::into_pin`]: ../../std/boxed/struct.Box.html#method.into_pin \"Box::into_pin\""] # [doc = " [subtle-details]: self#subtle-details-and-the-drop-guarantee \"pin subtle details\""] # [doc = " [`unsafe`]: ../../std/keyword.unsafe.html \"keyword unsafe\""] # [stable (feature = "pin" , since = "1.33.0")] # [lang = "pin"] # [fundamental] # [repr (transparent)] # [rustc_pub_transparent] # [derive (Copy , Clone)] pub struct Pin < Ptr > { pointer : Ptr , }}}
mkitem!{mkimpl!{# [stable (feature = "pin_trait_impls" , since = "1.41.0")] impl < Ptr : Deref , Q : Deref > PartialEq < Pin < Q > > for Pin < Ptr > where Ptr :: Target : PartialEq < Q :: Target > , { fn eq (& self , other : & Pin < Q >) -> bool { Ptr :: Target :: eq (self , other) } fn ne (& self , other : & Pin < Q >) -> bool { Ptr :: Target :: ne (self , other) } }}}
