mkitem!{mkimpl!{impl < Ptr : Deref < Target : Unpin > > Pin < Ptr > { # [doc = " Constructs a new `Pin<Ptr>` around a pointer to some data of a type that"] # [doc = " implements [`Unpin`]."] # [doc = ""] # [doc = " Unlike `Pin::new_unchecked`, this method is safe because the pointer"] # [doc = " `Ptr` dereferences to an [`Unpin`] type, which cancels the pinning guarantees."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " let mut val: u8 = 5;"] # [doc = ""] # [doc = " // Since `val` doesn't care about being moved, we can safely create a \"facade\" `Pin`"] # [doc = " // which will allow `val` to participate in `Pin`-bound apis  without checking that"] # [doc = " // pinning guarantees are actually upheld."] # [doc = " let mut pinned: Pin<&mut u8> = Pin::new(&mut val);"] # [doc = " ```"] # [inline (always)] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin" , since = "1.33.0")] pub const fn new (pointer : Ptr) -> Pin < Ptr > { unsafe { Pin :: new_unchecked (pointer) } } # [doc = " Unwraps this `Pin<Ptr>`, returning the underlying pointer."] # [doc = ""] # [doc = " Doing this operation safely requires that the data pointed at by this pinning pointer"] # [doc = " implements [`Unpin`] so that we can ignore the pinning invariants when unwrapping it."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " let mut val: u8 = 5;"] # [doc = " let pinned: Pin<&mut u8> = Pin::new(&mut val);"] # [doc = ""] # [doc = " // Unwrap the pin to get the underlying mutable reference to the value. We can do"] # [doc = " // this because `val` doesn't care about being moved, so the `Pin` was just"] # [doc = " // a \"facade\" anyway."] # [doc = " let r = Pin::into_inner(pinned);"] # [doc = " assert_eq!(*r, 5);"] # [doc = " ```"] # [inline (always)] # [rustc_allow_const_fn_unstable (const_precise_live_drops)] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin_into_inner" , since = "1.39.0")] pub const fn into_inner (pin : Pin < Ptr >) -> Ptr { pin . pointer } }}}
mkitem!{mkimpl!{impl < Ptr : Deref > Pin < Ptr > { # [doc = " Constructs a new `Pin<Ptr>` around a reference to some data of a type that"] # [doc = " may or may not implement [`Unpin`]."] # [doc = ""] # [doc = " If `pointer` dereferences to an [`Unpin`] type, [`Pin::new`] should be used"] # [doc = " instead."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This constructor is unsafe because we cannot guarantee that the data"] # [doc = " pointed to by `pointer` is pinned. At its core, pinning a value means making the"] # [doc = " guarantee that the value's data will not be moved nor have its storage invalidated until"] # [doc = " it gets dropped. For a more thorough explanation of pinning, see the [`pin` module docs]."] # [doc = ""] # [doc = " If the caller that is constructing this `Pin<Ptr>` does not ensure that the data `Ptr`"] # [doc = " points to is pinned, that is a violation of the API contract and may lead to undefined"] # [doc = " behavior in later (even safe) operations."] # [doc = ""] # [doc = " By using this method, you are also making a promise about the [`Deref`],"] # [doc = " [`DerefMut`], and [`Drop`] implementations of `Ptr`, if they exist. Most importantly, they"] # [doc = " must not move out of their `self` arguments: `Pin::as_mut` and `Pin::as_ref`"] # [doc = " will call `DerefMut::deref_mut` and `Deref::deref` *on the pointer type `Ptr`*"] # [doc = " and expect these methods to uphold the pinning invariants."] # [doc = " Moreover, by calling this method you promise that the reference `Ptr`"] # [doc = " dereferences to will not be moved out of again; in particular, it"] # [doc = " must not be possible to obtain a `&mut Ptr::Target` and then"] # [doc = " move out of that reference (using, for example [`mem::swap`])."] # [doc = ""] # [doc = " For example, calling `Pin::new_unchecked` on an `&'a mut T` is unsafe because"] # [doc = " while you are able to pin it for the given lifetime `'a`, you have no control"] # [doc = " over whether it is kept pinned once `'a` ends, and therefore cannot uphold the"] # [doc = " guarantee that a value, once pinned, remains pinned until it is dropped:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::mem;"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " fn move_pinned_ref<T>(mut a: T, mut b: T) {"] # [doc = "     unsafe {"] # [doc = "         let p: Pin<&mut T> = Pin::new_unchecked(&mut a);"] # [doc = "         // This should mean the pointee `a` can never move again."] # [doc = "     }"] # [doc = "     mem::swap(&mut a, &mut b); // Potential UB down the road ⚠\u{fe0f}"] # [doc = "     // The address of `a` changed to `b`'s stack slot, so `a` got moved even"] # [doc = "     // though we have previously pinned it! We have violated the pinning API contract."] # [doc = " }"] # [doc = " ```"] # [doc = " A value, once pinned, must remain pinned until it is dropped (unless its type implements"] # [doc = " `Unpin`). Because `Pin<&mut T>` does not own the value, dropping the `Pin` will not drop"] # [doc = " the value and will not end the pinning contract. So moving the value after dropping the"] # [doc = " `Pin<&mut T>` is still a violation of the API contract."] # [doc = ""] # [doc = " Similarly, calling `Pin::new_unchecked` on an `Rc<T>` is unsafe because there could be"] # [doc = " aliases to the same data that are not subject to the pinning restrictions:"] # [doc = " ```"] # [doc = " use std::rc::Rc;"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " fn move_pinned_rc<T>(mut x: Rc<T>) {"] # [doc = "     // This should mean the pointee can never move again."] # [doc = "     let pin = unsafe { Pin::new_unchecked(Rc::clone(&x)) };"] # [doc = "     {"] # [doc = "         let p: Pin<&T> = pin.as_ref();"] # [doc = "         // ..."] # [doc = "     }"] # [doc = "     drop(pin);"] # [doc = ""] # [doc = "     let content = Rc::get_mut(&mut x).unwrap(); // Potential UB down the road ⚠\u{fe0f}"] # [doc = "     // Now, if `x` was the only reference, we have a mutable reference to"] # [doc = "     // data that we pinned above, which we could use to move it as we have"] # [doc = "     // seen in the previous example. We have violated the pinning API contract."] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Pinning of closure captures"] # [doc = ""] # [doc = " Particular care is required when using `Pin::new_unchecked` in a closure:"] # [doc = " `Pin::new_unchecked(&mut var)` where `var` is a by-value (moved) closure capture"] # [doc = " implicitly makes the promise that the closure itself is pinned, and that *all* uses"] # [doc = " of this closure capture respect that pinning."] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = " use std::task::Context;"] # [doc = " use std::future::Future;"] # [doc = ""] # [doc = " fn move_pinned_closure(mut x: impl Future, cx: &mut Context<'_>) {"] # [doc = "     // Create a closure that moves `x`, and then internally uses it in a pinned way."] # [doc = "     let mut closure = move || unsafe {"] # [doc = "         let _ignore = Pin::new_unchecked(&mut x).poll(cx);"] # [doc = "     };"] # [doc = "     // Call the closure, so the future can assume it has been pinned."] # [doc = "     closure();"] # [doc = "     // Move the closure somewhere else. This also moves `x`!"] # [doc = "     let mut moved = closure;"] # [doc = "     // Calling it again means we polled the future from two different locations,"] # [doc = "     // violating the pinning API contract."] # [doc = "     moved(); // Potential UB ⚠\u{fe0f}"] # [doc = " }"] # [doc = " ```"] # [doc = " When passing a closure to another API, it might be moving the closure any time, so"] # [doc = " `Pin::new_unchecked` on closure captures may only be used if the API explicitly documents"] # [doc = " that the closure is pinned."] # [doc = ""] # [doc = " The better alternative is to avoid all that trouble and do the pinning in the outer function"] # [doc = " instead (here using the [`pin!`][crate::pin::pin] macro):"] # [doc = " ```"] # [doc = " use std::pin::pin;"] # [doc = " use std::task::Context;"] # [doc = " use std::future::Future;"] # [doc = ""] # [doc = " fn move_pinned_closure(mut x: impl Future, cx: &mut Context<'_>) {"] # [doc = "     let mut x = pin!(x);"] # [doc = "     // Create a closure that captures `x: Pin<&mut _>`, which is safe to move."] # [doc = "     let mut closure = move || {"] # [doc = "         let _ignore = x.as_mut().poll(cx);"] # [doc = "     };"] # [doc = "     // Call the closure, so the future can assume it has been pinned."] # [doc = "     closure();"] # [doc = "     // Move the closure somewhere else."] # [doc = "     let mut moved = closure;"] # [doc = "     // Calling it again here is fine (except that we might be polling a future that already"] # [doc = "     // returned `Poll::Ready`, but that is a separate problem)."] # [doc = "     moved();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [`mem::swap`]: crate::mem::swap"] # [doc = " [`pin` module docs]: self"] # [lang = "new_unchecked"] # [inline (always)] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin" , since = "1.33.0")] pub const unsafe fn new_unchecked (pointer : Ptr) -> Pin < Ptr > { Pin { pointer } } # [doc = " Gets a shared reference to the pinned value this [`Pin`] points to."] # [doc = ""] # [doc = " This is a generic method to go from `&Pin<Pointer<T>>` to `Pin<&T>`."] # [doc = " It is safe because, as part of the contract of `Pin::new_unchecked`,"] # [doc = " the pointee cannot move after `Pin<Pointer<T>>` got created."] # [doc = " \"Malicious\" implementations of `Pointer::Deref` are likewise"] # [doc = " ruled out by the contract of `Pin::new_unchecked`."] # [stable (feature = "pin" , since = "1.33.0")] # [inline (always)] # [rustc_const_unstable (feature = "const_convert" , issue = "143773")] pub const fn as_ref (& self) -> Pin < & Ptr :: Target > where Ptr : [const] Deref , { unsafe { Pin :: new_unchecked (& * self . pointer) } } }}}
mkitem!{mkimpl!{impl < Ptr : DerefMut > Pin < Ptr > { # [doc = " Gets a mutable reference to the pinned value this `Pin<Ptr>` points to."] # [doc = ""] # [doc = " This is a generic method to go from `&mut Pin<Pointer<T>>` to `Pin<&mut T>`."] # [doc = " It is safe because, as part of the contract of `Pin::new_unchecked`,"] # [doc = " the pointee cannot move after `Pin<Pointer<T>>` got created."] # [doc = " \"Malicious\" implementations of `Pointer::DerefMut` are likewise"] # [doc = " ruled out by the contract of `Pin::new_unchecked`."] # [doc = ""] # [doc = " This method is useful when doing multiple calls to functions that consume the"] # [doc = " pinning pointer."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " # struct Type {}"] # [doc = " impl Type {"] # [doc = "     fn method(self: Pin<&mut Self>) {"] # [doc = "         // do something"] # [doc = "     }"] # [doc = ""] # [doc = "     fn call_method_twice(mut self: Pin<&mut Self>) {"] # [doc = "         // `method` consumes `self`, so reborrow the `Pin<&mut Self>` via `as_mut`."] # [doc = "         self.as_mut().method();"] # [doc = "         self.as_mut().method();"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [stable (feature = "pin" , since = "1.33.0")] # [inline (always)] # [rustc_const_unstable (feature = "const_convert" , issue = "143773")] pub const fn as_mut (& mut self) -> Pin < & mut Ptr :: Target > where Ptr : [const] DerefMut , { unsafe { Pin :: new_unchecked (& mut * self . pointer) } } # [doc = " Gets `Pin<&mut T>` to the underlying pinned value from this nested `Pin`-pointer."] # [doc = ""] # [doc = " This is a generic method to go from `Pin<&mut Pin<Pointer<T>>>` to `Pin<&mut T>`. It is"] # [doc = " safe because the existence of a `Pin<Pointer<T>>` ensures that the pointee, `T`, cannot"] # [doc = " move in the future, and this method does not enable the pointee to move. \"Malicious\""] # [doc = " implementations of `Ptr::DerefMut` are likewise ruled out by the contract of"] # [doc = " `Pin::new_unchecked`."] # [stable (feature = "pin_deref_mut" , since = "1.84.0")] # [must_use = "`self` will be dropped if the result is not used"] # [inline (always)] # [rustc_const_unstable (feature = "const_convert" , issue = "143773")] pub const fn as_deref_mut (self : Pin < & mut Self >) -> Pin < & mut Ptr :: Target > where Ptr : [const] DerefMut , { unsafe { self . get_unchecked_mut () } . as_mut () } # [doc = " Assigns a new value to the memory location pointed to by the `Pin<Ptr>`."] # [doc = ""] # [doc = " This overwrites pinned data, but that is okay: the original pinned value's destructor gets"] # [doc = " run before being overwritten and the new value is also a valid value of the same type, so"] # [doc = " no pinning invariant is violated. See [the `pin` module documentation][subtle-details]"] # [doc = " for more information on how this upholds the pinning invariants."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " let mut val: u8 = 5;"] # [doc = " let mut pinned: Pin<&mut u8> = Pin::new(&mut val);"] # [doc = " println!(\"{}\", pinned); // 5"] # [doc = " pinned.set(10);"] # [doc = " println!(\"{}\", pinned); // 10"] # [doc = " ```"] # [doc = ""] # [doc = " [subtle-details]: self#subtle-details-and-the-drop-guarantee"] # [stable (feature = "pin" , since = "1.33.0")] # [inline (always)] pub fn set (& mut self , value : Ptr :: Target) where Ptr :: Target : Sized , { * (self . pointer) = value ; } }}}
mkitem!{mkimpl!{impl < Ptr : Deref > Pin < Ptr > { # [doc = " Unwraps this `Pin<Ptr>`, returning the underlying `Ptr`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This function is unsafe. You must guarantee that you will continue to"] # [doc = " treat the pointer `Ptr` as pinned after you call this function, so that"] # [doc = " the invariants on the `Pin` type can be upheld. If the code using the"] # [doc = " resulting `Ptr` does not continue to maintain the pinning invariants that"] # [doc = " is a violation of the API contract and may lead to undefined behavior in"] # [doc = " later (safe) operations."] # [doc = ""] # [doc = " Note that you must be able to guarantee that the data pointed to by `Ptr`"] # [doc = " will be treated as pinned all the way until its `drop` handler is complete!"] # [doc = ""] # [doc = " *For more information, see the [`pin` module docs][self]*"] # [doc = ""] # [doc = " If the underlying data is [`Unpin`], [`Pin::into_inner`] should be used"] # [doc = " instead."] # [inline (always)] # [rustc_allow_const_fn_unstable (const_precise_live_drops)] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin_into_inner" , since = "1.39.0")] pub const unsafe fn into_inner_unchecked (pin : Pin < Ptr >) -> Ptr { pin . pointer } }}}
mkitem!{mkimpl!{impl < 'a , T : ? Sized > Pin < & 'a T > { # [doc = " Constructs a new pin by mapping the interior value."] # [doc = ""] # [doc = " For example, if you wanted to get a `Pin` of a field of something,"] # [doc = " you could use this to get access to that field in one line of code."] # [doc = " However, there are several gotchas with these \"pinning projections\";"] # [doc = " see the [`pin` module] documentation for further details on that topic."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This function is unsafe. You must guarantee that the data you return"] # [doc = " will not move so long as the argument value does not move (for example,"] # [doc = " because it is one of the fields of that value), and also that you do"] # [doc = " not move out of the argument you receive to the interior function."] # [doc = ""] # [doc = " [`pin` module]: self#projections-and-structural-pinning"] # [stable (feature = "pin" , since = "1.33.0")] pub unsafe fn map_unchecked < U , F > (self , func : F) -> Pin < & 'a U > where U : ? Sized , F : FnOnce (& T) -> & U , { let pointer = & * self . pointer ; let new_pointer = func (pointer) ; unsafe { Pin :: new_unchecked (new_pointer) } } # [doc = " Gets a shared reference out of a pin."] # [doc = ""] # [doc = " This is safe because it is not possible to move out of a shared reference."] # [doc = " It may seem like there is an issue here with interior mutability: in fact,"] # [doc = " it *is* possible to move a `T` out of a `&RefCell<T>`. However, this is"] # [doc = " not a problem as long as there does not also exist a `Pin<&T>` pointing"] # [doc = " to the inner `T` inside the `RefCell`, and `RefCell<T>` does not let you get a"] # [doc = " `Pin<&T>` pointer to its contents. See the discussion on [\"pinning projections\"]"] # [doc = " for further details."] # [doc = ""] # [doc = " Note: `Pin` also implements `Deref` to the target, which can be used"] # [doc = " to access the inner value. However, `Deref` only provides a reference"] # [doc = " that lives for as long as the borrow of the `Pin`, not the lifetime of"] # [doc = " the reference contained in the `Pin`. This method allows turning the `Pin` into a reference"] # [doc = " with the same lifetime as the reference it wraps."] # [doc = ""] # [doc = " [\"pinning projections\"]: self#projections-and-structural-pinning"] # [inline (always)] # [must_use] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin" , since = "1.33.0")] pub const fn get_ref (self) -> & 'a T { self . pointer } }}}
mkitem!{mkimpl!{impl < 'a , T : ? Sized > Pin < & 'a mut T > { # [doc = " Converts this `Pin<&mut T>` into a `Pin<&T>` with the same lifetime."] # [inline (always)] # [must_use = "`self` will be dropped if the result is not used"] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] # [stable (feature = "pin" , since = "1.33.0")] pub const fn into_ref (self) -> Pin < & 'a T > { Pin { pointer : self . pointer } } # [doc = " Gets a mutable reference to the data inside of this `Pin`."] # [doc = ""] # [doc = " This requires that the data inside this `Pin` is `Unpin`."] # [doc = ""] # [doc = " Note: `Pin` also implements `DerefMut` to the data, which can be used"] # [doc = " to access the inner value. However, `DerefMut` only provides a reference"] # [doc = " that lives for as long as the borrow of the `Pin`, not the lifetime of"] # [doc = " the `Pin` itself. This method allows turning the `Pin` into a reference"] # [doc = " with the same lifetime as the original `Pin`."] # [inline (always)] # [must_use = "`self` will be dropped if the result is not used"] # [stable (feature = "pin" , since = "1.33.0")] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] pub const fn get_mut (self) -> & 'a mut T where T : Unpin , { self . pointer } # [doc = " Gets a mutable reference to the data inside of this `Pin`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This function is unsafe. You must guarantee that you will never move"] # [doc = " the data out of the mutable reference you receive when you call this"] # [doc = " function, so that the invariants on the `Pin` type can be upheld."] # [doc = ""] # [doc = " If the underlying data is `Unpin`, `Pin::get_mut` should be used"] # [doc = " instead."] # [inline (always)] # [must_use = "`self` will be dropped if the result is not used"] # [stable (feature = "pin" , since = "1.33.0")] # [rustc_const_stable (feature = "const_pin" , since = "1.84.0")] pub const unsafe fn get_unchecked_mut (self) -> & 'a mut T { self . pointer } # [doc = " Constructs a new pin by mapping the interior value."] # [doc = ""] # [doc = " For example, if you wanted to get a `Pin` of a field of something,"] # [doc = " you could use this to get access to that field in one line of code."] # [doc = " However, there are several gotchas with these \"pinning projections\";"] # [doc = " see the [`pin` module] documentation for further details on that topic."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This function is unsafe. You must guarantee that the data you return"] # [doc = " will not move so long as the argument value does not move (for example,"] # [doc = " because it is one of the fields of that value), and also that you do"] # [doc = " not move out of the argument you receive to the interior function."] # [doc = ""] # [doc = " [`pin` module]: self#projections-and-structural-pinning"] # [must_use = "`self` will be dropped if the result is not used"] # [stable (feature = "pin" , since = "1.33.0")] pub unsafe fn map_unchecked_mut < U , F > (self , func : F) -> Pin < & 'a mut U > where U : ? Sized , F : FnOnce (& mut T) -> & mut U , { let pointer = unsafe { Pin :: get_unchecked_mut (self) } ; let new_pointer = func (pointer) ; unsafe { Pin :: new_unchecked (new_pointer) } } }}}
