mkitem!{# [doc = " Constructs a <code>[Pin]<[&mut] T></code>, by pinning a `value: T` locally."] # [doc = ""] # [doc = " Unlike [`Box::pin`], this does not create a new heap allocation. As explained"] # [doc = " below, the element might still end up on the heap however."] # [doc = ""] # [doc = " The local pinning performed by this macro is usually dubbed \"stack\"-pinning."] # [doc = " Outside of `async` contexts locals do indeed get stored on the stack. In"] # [doc = " `async` functions or blocks however, any locals crossing an `.await` point"] # [doc = " are part of the state captured by the `Future`, and will use the storage of"] # [doc = " those. That storage can either be on the heap or on the stack. Therefore,"] # [doc = " local pinning is a more accurate term."] # [doc = ""] # [doc = " If the type of the given value does not implement [`Unpin`], then this macro"] # [doc = " pins the value in memory in a way that prevents moves. On the other hand,"] # [doc = " if the type does implement [`Unpin`], <code>[Pin]<[&mut] T></code> behaves"] # [doc = " like <code>[&mut] T</code>, and operations such as"] # [doc = " [`mem::replace()`][crate::mem::replace] or [`mem::take()`](crate::mem::take)"] # [doc = " will allow moves of the value."] # [doc = " See [the `Unpin` section of the `pin` module][self#unpin] for details."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " ### Basic usage"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use core::marker::PhantomPinned as Foo;"] # [doc = " use core::pin::{pin, Pin};"] # [doc = ""] # [doc = " fn stuff(foo: Pin<&mut Foo>) {"] # [doc = "     // …"] # [doc = "     # let _ = foo;"] # [doc = " }"] # [doc = ""] # [doc = " let pinned_foo = pin!(Foo { /* … */ });"] # [doc = " stuff(pinned_foo);"] # [doc = " // or, directly:"] # [doc = " stuff(pin!(Foo { /* … */ }));"] # [doc = " ```"] # [doc = ""] # [doc = " ### Manually polling a `Future` (without `Unpin` bounds)"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::{"] # [doc = "     future::Future,"] # [doc = "     pin::pin,"] # [doc = "     task::{Context, Poll},"] # [doc = "     thread,"] # [doc = " };"] # [doc = " # use std::{sync::Arc, task::Wake, thread::Thread};"] # [doc = ""] # [doc = " # /// A waker that wakes up the current thread when called."] # [doc = " # struct ThreadWaker(Thread);"] # [doc = " #"] # [doc = " # impl Wake for ThreadWaker {"] # [doc = " #     fn wake(self: Arc<Self>) {"] # [doc = " #         self.0.unpark();"] # [doc = " #     }"] # [doc = " # }"] # [doc = " #"] # [doc = " /// Runs a future to completion."] # [doc = " fn block_on<Fut: Future>(fut: Fut) -> Fut::Output {"] # [doc = "     let waker_that_unparks_thread = // …"] # [doc = "         # Arc::new(ThreadWaker(thread::current())).into();"] # [doc = "     let mut cx = Context::from_waker(&waker_that_unparks_thread);"] # [doc = "     // Pin the future so it can be polled."] # [doc = "     let mut pinned_fut = pin!(fut);"] # [doc = "     loop {"] # [doc = "         match pinned_fut.as_mut().poll(&mut cx) {"] # [doc = "             Poll::Pending => thread::park(),"] # [doc = "             Poll::Ready(res) => return res,"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " #"] # [doc = " # assert_eq!(42, block_on(async { 42 }));"] # [doc = " ```"] # [doc = ""] # [doc = " ### With `Coroutine`s"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(coroutines)]"] # [doc = " #![feature(coroutine_trait)]"] # [doc = " use core::{"] # [doc = "     ops::{Coroutine, CoroutineState},"] # [doc = "     pin::pin,"] # [doc = " };"] # [doc = ""] # [doc = " fn coroutine_fn() -> impl Coroutine<Yield = usize, Return = ()> /* not Unpin */ {"] # [doc = "  // Allow coroutine to be self-referential (not `Unpin`)"] # [doc = "  // vvvvvv        so that locals can cross yield points."] # [doc = "     #[coroutine] static || {"] # [doc = "         let foo = String::from(\"foo\");"] # [doc = "         let foo_ref = &foo; // ------+"] # [doc = "         yield 0;                  // | <- crosses yield point!"] # [doc = "         println!(\"{foo_ref}\"); // <--+"] # [doc = "         yield foo.len();"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let mut coroutine = pin!(coroutine_fn());"] # [doc = "     match coroutine.as_mut().resume(()) {"] # [doc = "         CoroutineState::Yielded(0) => {},"] # [doc = "         _ => unreachable!(),"] # [doc = "     }"] # [doc = "     match coroutine.as_mut().resume(()) {"] # [doc = "         CoroutineState::Yielded(3) => {},"] # [doc = "         _ => unreachable!(),"] # [doc = "     }"] # [doc = "     match coroutine.resume(()) {"] # [doc = "         CoroutineState::Yielded(_) => unreachable!(),"] # [doc = "         CoroutineState::Complete(()) => {},"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Remarks"] # [doc = ""] # [doc = " Precisely because a value is pinned to local storage, the resulting <code>[Pin]<[&mut] T></code>"] # [doc = " reference ends up borrowing a local tied to that block: it can't escape it."] # [doc = ""] # [doc = " The following, for instance, fails to compile:"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " use core::pin::{pin, Pin};"] # [doc = " # use core::{marker::PhantomPinned as Foo, mem::drop as stuff};"] # [doc = ""] # [doc = " let x: Pin<&mut Foo> = {"] # [doc = "     let x: Pin<&mut Foo> = pin!(Foo { /* … */ });"] # [doc = "     x"] # [doc = " }; // <- Foo is dropped"] # [doc = " stuff(x); // Error: use of dropped value"] # [doc = " ```"] # [doc = ""] # [doc = " <details><summary>Error message</summary>"] # [doc = ""] # [doc = " ```console"] # [doc = " error[E0716]: temporary value dropped while borrowed"] # [doc = "   --> src/main.rs:9:28"] # [doc = "    |"] # [doc = " 8  | let x: Pin<&mut Foo> = {"] # [doc = "    |     - borrow later stored here"] # [doc = " 9  |     let x: Pin<&mut Foo> = pin!(Foo { /* … */ });"] # [doc = "    |                            ^^^^^^^^^^^^^^^^^^^^^ creates a temporary value which is freed while still in use"] # [doc = " 10 |     x"] # [doc = " 11 | }; // <- Foo is dropped"] # [doc = "    | - temporary value is freed at the end of this statement"] # [doc = "    |"] # [doc = "    = note: consider using a `let` binding to create a longer lived value"] # [doc = " ```"] # [doc = ""] # [doc = " </details>"] # [doc = ""] # [doc = " This makes [`pin!`] **unsuitable to pin values when intending to _return_ them**. Instead, the"] # [doc = " value is expected to be passed around _unpinned_ until the point where it is to be consumed,"] # [doc = " where it is then useful and even sensible to pin the value locally using [`pin!`]."] # [doc = ""] # [doc = " If you really need to return a pinned value, consider using [`Box::pin`] instead."] # [doc = ""] # [doc = " On the other hand, local pinning using [`pin!`] is likely to be cheaper than"] # [doc = " pinning into a fresh heap allocation using [`Box::pin`]. Moreover, by virtue of not"] # [doc = " requiring an allocator, [`pin!`] is the main non-`unsafe` `#![no_std]`-compatible [`Pin`]"] # [doc = " constructor."] # [doc = ""] # [doc = " [`Box::pin`]: ../../std/boxed/struct.Box.html#method.pin"] # [stable (feature = "pin_macro" , since = "1.68.0")] # [rustc_macro_transparency = "semitransparent"] # [allow_internal_unstable (super_let)] # [rustc_diagnostic_item = "pin_macro"] # [rustfmt :: skip] pub macro pin ($ value : expr $ (,) ?) { { super let mut pinned = $ value ; unsafe { $ crate :: pin :: Pin :: new_unchecked (& mut pinned) } } }}